{
  "findings": [
    {
      "check_id": "CKV_AWS_28",
      "title": "AMI EBS Block Device Not Encrypted",
      "resource": "aws_ami.pass",
      "severity": "HIGH",
      "explanation": "The first ebs_block_device block does not explicitly set 'encrypted = true'. While it references a snapshot, relying on implicit encryption or unencrypted snapshots can lead to data exposure at rest. Explicitly setting encryption ensures the volume is encrypted regardless of the source snapshot's state."
    }
  ],
  "patched_code": "resource "aws_ami" "pass" {
  name                = "terraform-example"
  virtualization_type = "hvm"
  root_device_name    = "/dev/xvda1"

  ebs_block_device {
    device_name = "/dev/xvda1"
    volume_size = 8
    snapshot_id = "someid"
    encrypted   = true
  }

  ebs_block_device {
    device_name = "/dev/xvda2"
    volume_size = 8
    encrypted   = true
  }
}
",
  "fix_summary": "Added 'encrypted = true' to the first ebs_block_device block in the aws_ami resource to ensure all EBS volumes associated with the AMI are encrypted at rest."
}
